[Form]
public class METPriceComponentSalesOrder extends FormRun
{
    SalesLine                           salesLine;
    METSalesLinePriceComponentTmp       tmpTable;
    
    public const int basePrice = 1;
    public const int margin = 2;
    public const int unitPrice = 3;
    public const int discount = 4;
    public const int netAmount = 5;
    public const int lineCharge = 6;

}

        /// <summary>
        /// Datasource init method
        /// </summary>
        public void init()
        {
            super();

            if (element.args().dataset() == tableNum(SalesLine))
            {
                salesLine = element.args().record();
            }

            METSalesLinePriceComponentTmp.linkPhysicalTableInstance(this.insertTmp());

            METSalesLinePriceComponentTmp_ds.queryBuildDataSource().addSortField(fieldNum(METSalesLinePriceComponentTmp, LineNum));
        }

        /// <summary>
        /// Method to insert calculated records in temp table
        /// </summary>
        /// <returns>METSalesLinePriceComponentTmp</returns>
        public METSalesLinePriceComponentTmp insertTmp()
        {
            METSalesLinePriceComponent      salesLinePriceComponent;
            METPriceComponent               priceComponent;
            Amount                          unitPriceAmount;
            Amount                          extPriceAmount;
            Amount                          discountValueAmount;
            Amount                          discountExtValueAmount;
            boolean                         recordInserted;
            RecordInsertList                tmpRecordInsertList = new RecordInsertList(tableNum(METSalesLinePriceComponentTmp), false, false, false, false, false, tmpTable);

            while select salesLinePriceComponent where salesLinePriceComponent.InventTransId == salesLine.InventTransId
            {
                tmpTable.InventTransId  = salesLinePriceComponent.InventTransId;
                tmpTable.Component      = salesLinePriceComponent.Component;
                tmpTable.PriceCodeRef   = salesLinePriceComponent.PriceCodeRef;
                tmpTable.Value          = salesLinePriceComponent.Value;
                tmpTable.PriceComponent = METComponentCode::findComponent(tmpTable.Component).PriceComponent;
                tmpTable.ExtValue       = tmpTable.Value * salesLine.SalesQty;

                priceComponent = METComponentCode::findComponent(salesLinePriceComponent.Component).PriceComponent;

                switch (priceComponent)
                {
                    case METPriceComponent::BasePrice:

                        tmpTable.LineNum = basePrice;
                        unitPriceAmount += tmpTable.Value;
                        extPriceAmount  += tmpTable.ExtValue;

                        break;

                    case METPriceComponent::Discounts:

                        tmpTable.LineNum        = discount;
                        discountValueAmount     += tmpTable.Value;
                        discountExtValueAmount  += tmpTable.ExtValue;

                        break;

                    case METPriceComponent::LineCharges:

                        tmpTable.LineNum = lineCharge;

                        break;

                    case METPriceComponent::Margins:

                        tmpTable.LineNum = margin;
                        unitPriceAmount += tmpTable.Value;
                        extPriceAmount  += tmpTable.ExtValue;

                        break;
                }

                tmpRecordInsertList.add(tmpTable);
                tmpTable.clear();

                recordInserted = true;
            }

            if (recordInserted)
            {
                //Insert calculated Unit price and net amount as a seperate line
                tmpTable.InventTransId  = salesLinePriceComponent.InventTransId;
                tmpTable.PriceComponent = METPriceComponent::UnitPrice;
                tmpTable.Value          = unitPriceAmount;
                tmpTable.ExtValue       = extPriceAmount;
                tmpTable.LineNum        = unitPrice;

                tmpRecordInsertList.add(tmpTable);
                tmpTable.clear();

                tmpTable.InventTransId  = salesLinePriceComponent.InventTransId;
                tmpTable.PriceComponent = METPriceComponent::NetAmount;
                tmpTable.Value          = unitPriceAmount - discountValueAmount;
                tmpTable.ExtValue       = extPriceAmount - discountExtValueAmount;
                tmpTable.LineNum        = netAmount;

                tmpRecordInsertList.add(tmpTable);
                tmpTable.clear();
            }

            tmpRecordInsertList.insertDatabase();

            return tmpTable;
        }

        /// <summary>
        /// Datasource active method
        /// </summary>
        /// <returns>Integer reference</returns>
        public int active()
        {
            int ret;
        
            ret = super();

            //Unable to link the tmp table with regular table hence filtering child table on active method

            METSalesLinePriceComponentDetail_ds.executeQuery();
        
            return ret;
        }

        /// <summary>
        /// Datasource init method
        /// </summary>
        public void init()
        {
            super();

            SysQuery::findOrCreateRange(METSalesLinePriceComponentDetail_ds.queryBuildDataSource(), fieldNum(METSalesLinePriceComponentDetail, InventTransId)).value(queryValue(salesLine.InventTransId));
        }

        /// <summary>
        /// Datasource executequery method
        /// </summary>
        public void executeQuery()
        {
            METSalesLinePriceComponentDetail_ds.queryBuildDataSource().clearRange(fieldNum(METSalesLinePriceComponentDetail, Component));

            SysQuery::findOrCreateRange(METSalesLinePriceComponentDetail_ds.queryBuildDataSource(), fieldNum(METSalesLinePriceComponentDetail, Component)).value(queryValue(METSalesLinePriceComponentTmp.Component));
            super();
        }
